@ExtendWith(MockitoExtension.class)
class PedidoServiceTest {
    @Mock EmailClient emailClient;
    @InjectMocks PedidoService service;

    @Test
    void capturaEmailEnviado() {
        ArgumentCaptor<String> captor = ArgumentCaptor.forClass(String.class);
        service.confirmar("ana@dev.com");
        verify(emailClient, times(1)).enviar(captor.capture());
        assertEquals("ana@dev.com", captor.getValue());
    }
}

